-- Canonical bundled ingredients and recipes. user_id IS NULL means shared.

UPDATE ingredients SET name_key = LOWER(TRIM(name_zh)) WHERE name_key = '';
UPDATE recipes SET name_key = LOWER(TRIM(name_zh)) WHERE name_key = '';
UPDATE recipes SET name_en = NULL WHERE name_en = '';
UPDATE recipes SET description = NULL WHERE description = '';
UPDATE recipes SET method = NULL WHERE method = '';
UPDATE recipes SET image_url = NULL WHERE image_url = '';
