INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('margarita-classic','玛格丽特','Margarita','classic','经典龙舌兰鸡尾酒，酸甜平衡，是全球最受欢迎的鸡尾酒之一','摇和法 (Shake)','{"sweet": 2, "sour": 4, "bitter": 1, "strong": 3}',NULL,'IBA',TO_TIMESTAMP(1780733215),TO_TIMESTAMP(1780733215));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('mojito-classic','莫吉托','Mojito','tropical','古巴经典鸡尾酒，清爽薄荷风味，夏日首选','捣和法 (Muddle & Build)','{"sweet": 3, "sour": 3, "bitter": 0, "strong": 2}',NULL,'IBA',TO_TIMESTAMP(1780733215),TO_TIMESTAMP(1780733215));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('white-russian','白俄罗斯','White Russian','classic','奶油咖啡味鸡尾酒，口感丝滑香甜','直调法 (Build)','{"sweet": 4, "sour": 0, "bitter": 2, "strong": 3}',NULL,'IBA',TO_TIMESTAMP(1780733215),TO_TIMESTAMP(1780733215));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-01','干马天尼','Dry Martini','Gin','鸡尾酒之王，极简而纯粹。由金酒与干味美思完美平衡，散发迷人的植物香气。','stir','{"sweet": 1, "sour": 0, "bitter": 3, "strong": 5}','martini.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-02','尼格罗尼','Negroni','Gin','意大利的经典之作。三种酒1:1:1的黄金比例，苦中带甜，风味深邃复杂。','build','{"sweet": 3, "sour": 0, "bitter": 4, "strong": 4}','negroni.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-03','金汤力','Gin & Tonic','Gin','最广为人知的金酒长饮。奎宁水的微苦与金酒的杜松子香气完美结合，气泡升腾，极致清凉。','build','{"sweet": 2, "sour": 2, "bitter": 2, "strong": 2}','gin_and_tonic.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-04','吉姆雷特','Gimlet','Gin','极简的酸甜平衡艺术。金酒的植物芬芳被青柠的酸冽彻底激发，锐利而迷人。','shake','{"sweet": 2, "sour": 4, "bitter": 0, "strong": 3}','gimlet.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-05','飞行','Aviation','Gin','呈现梦幻的淡紫色，黑樱桃与紫罗兰的馥郁花果香在舌尖绽放，如漫步云端。','shake','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 3}','aviation.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-06','汤姆·柯林斯','Tom Collins','Gin','简单直白的解渴利器。清新的柠檬酸味和苏打水的气泡完美中和了烈酒的灼烧感。','shake','{"sweet": 2, "sour": 3, "bitter": 0, "strong": 2}','tom_collins.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-07','新加坡司令','Singapore Sling','Gin','复杂的配方造就了层次极为丰富的热带水果风味，鲜艳的粉红色外观令人垂涎。','shake','{"sweet": 4, "sour": 2, "bitter": 1, "strong": 2}','singapore_sling.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-08','法式75','French 75','Gin','起泡酒的奢华与金酒的凛冽交织，口感明快，有着如大炮般的后劲。','shake','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 3}','french_75.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-09','亡者复苏二号','Corpse Reviver No. 2','Gin','四大等份原料带来绝对的平衡，淡淡的苦艾酒香气穿梭其中，有着让人瞬间清醒的魔力。','shake','{"sweet": 2, "sour": 3, "bitter": 2, "strong": 3}','corpse_reviver.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-gin-10','三叶草俱乐部','Clover Club','Gin','覆盆子的酸甜果香与干味美思的植物香料完美交融，表面覆盖一层如云朵般绵密的蛋白泡沫。','shake','{"sweet": 3, "sour": 3, "bitter": 0, "strong": 2}','clover_club.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-01','老式','Old Fashioned','Whiskey','最初的“鸡尾酒”定义本身。威士忌、糖、水和苦精的纯粹组合，尽显烈酒本色。','build','{"sweet": 2, "sour": 0, "bitter": 3, "strong": 5}','old_fashioned.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-02','曼哈顿','Manhattan','Whiskey','鸡尾酒王后。黑麦威士忌的辛辣与甜味美思的草本甜香完美交织，有着高贵的女王气质。','stir','{"sweet": 3, "sour": 0, "bitter": 2, "strong": 4}','manhattan.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-03','威士忌酸','Whiskey Sour','Whiskey','波本威士忌的焦糖香与柠檬的清爽酸味完美平衡，加入蛋清带来如丝绸般顺滑的泡沫口感。','shake','{"sweet": 3, "sour": 4, "bitter": 1, "strong": 3}','whiskey_sour.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-04','薄荷朱丽普','Mint Julep','Whiskey','波本威士忌与新鲜薄荷的极致清凉碰撞，盛装在结满冰霜的银杯中，是美国南部的象征。','muddle','{"sweet": 2, "sour": 0, "bitter": 1, "strong": 4}','mint_julep.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-05','花花公子','Boulevardier','Whiskey','尼格罗尼的波本威士忌变体，但更温暖、浓郁，充满了深沉的木质香与复杂的苦甜交织。','build','{"sweet": 3, "sour": 0, "bitter": 4, "strong": 4}','boulevardier.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-06','萨泽拉克','Sazerac','Whiskey','新奥尔良的官方鸡尾酒。杯壁那抹若有若无的苦艾酒香气，与黑麦威士忌的辛辣完美融合。','stir','{"sweet": 2, "sour": 0, "bitter": 3, "strong": 5}','sazerac.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-07','爱尔兰咖啡','Irish Coffee','Whiskey','热咖啡的香浓、爱尔兰威士忌的烈性与鲜奶油的冰凉绵密在口中交融，是寒冬最暖心的安慰。','build','{"sweet": 3, "sour": 0, "bitter": 3, "strong": 3}','irish_coffee.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-08','盘尼西林','Penicillin','Whiskey','21世纪最伟大的现代经典。生姜的辛辣、蜂蜜的滋润与艾雷岛威士忌那迷人的泥煤消毒水味，堪称绝妙的治愈灵药。','shake','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 4}','penicillin.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-09','生锈钉','Rusty Nail','Whiskey','极简至极的双料鸡尾酒。苏格兰威士忌的坚韧与杜林标（Drambuie）利口酒的蜂蜜草药香完美融合，浓烈而圆润。','build','{"sweet": 3, "sour": 0, "bitter": 1, "strong": 5}','rusty_nail.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-whiskey-10','血与沙','Blood and Sand','Whiskey','少见的含有果汁的苏格兰威士忌鸡尾酒，橙汁的甜味与樱桃利口酒的果香奇妙地柔和了威士忌的锋芒。','shake','{"sweet": 4, "sour": 2, "bitter": 1, "strong": 3}','blood_and_sand.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-01','莫吉托','Mojito','Rum','古巴的国民饮料。白朗姆酒、新鲜薄荷与青柠的完美结合，清爽解渴的极致代表。','muddle','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 2}','mojito.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-02','大吉岭','Daiquiri','Rum','极其纯粹的酸甜平衡艺术。只有朗姆酒、青柠汁和糖浆三样原料，却千变万化。','shake','{"sweet": 2, "sour": 4, "bitter": 0, "strong": 3}','daiquiri.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-03','椰林飘香','Piña Colada','Rum','终极的热带度假饮品。椰浆的醇厚奶香与菠萝的酸甜果味完美交融，仿佛置身加勒比海滩。','blend','{"sweet": 5, "sour": 2, "bitter": 0, "strong": 2}','pina_colada.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-04','迈泰','Mai Tai','Rum','Tiki 文化的巅峰之作。多重朗姆酒的陈年木香、杏仁糖浆的坚果味与新鲜柑橘结合，狂野而深邃。','shake','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 4}','mai_tai.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-05','自由古巴','Cuba Libre','Rum','极简的长饮代表。冰镇可乐带来的刺激气泡搭配陈年朗姆酒的甘蔗香甜，青柠汁是注入灵魂的关键。','build','{"sweet": 4, "sour": 1, "bitter": 0, "strong": 2}','cuba_libre.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-06','月黑风高','Dark ''n'' Stormy','Rum','黑朗姆酒漂浮在辛辣的姜汁啤酒上，如同风暴来临前昏暗汹涌的海面，口感炽烈而清爽。','build','{"sweet": 3, "sour": 2, "bitter": 1, "strong": 3}','dark_n_stormy.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-07','僵尸','Zombie','Rum','名副其实的致命诱惑。混合了三种不同年份和烈度的朗姆酒与大量热带果汁，喝下后足以让人像僵尸一样失去意识。','blend','{"sweet": 4, "sour": 3, "bitter": 1, "strong": 5}','zombie.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-08','丛林鸟','Jungle Bird','Rum','罕见的带有浓郁苦味的Tiki鸡尾酒，金巴利的苦味与菠萝汁的甜美形成绝妙的冲突美学。','shake','{"sweet": 3, "sour": 2, "bitter": 3, "strong": 3}','jungle_bird.png','Contemporary Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-09','海明威特调','Hemingway Special','Rum','为嗜酒如命的大文豪量身定制，酸涩凛冽的葡萄柚与黑樱桃酒香取代了糖浆的甜腻，极其强劲。','shake','{"sweet": 1, "sour": 5, "bitter": 2, "strong": 4}','hemingway_special.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-rum-10','玛丽·毕克馥','Mary Pickford','Rum','呈现娇艳的粉红色，菠萝的香甜与黑樱桃的果味交织，如好莱坞明星般甜美迷人。','shake','{"sweet": 4, "sour": 1, "bitter": 0, "strong": 3}','mary_pickford.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-01','玛格丽特','Margarita','Tequila','全球最著名的龙舌兰鸡尾酒。杯口的盐边完美提升了龙舌兰的植物香气与青柠的酸涩，回味无穷。','shake','{"sweet": 2, "sour": 4, "bitter": 1, "strong": 3}','margarita.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-02','龙舌兰日出','Tequila Sunrise','Tequila','拥有迷人的渐变色彩，宛如清晨升起的太阳，橙汁的甜美中和了龙舌兰的浓烈。','build','{"sweet": 4, "sour": 2, "bitter": 0, "strong": 2}','tequila_sunrise.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-03','帕洛玛','Paloma','Tequila','比玛格丽特更受墨西哥本地人欢迎的国民饮料。西柚汽水的微苦与青柠的酸爽，将龙舌兰的花香完美激发。','build','{"sweet": 2, "sour": 3, "bitter": 2, "strong": 2}','paloma.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-04','汤米玛格丽特','Tommy''s Margarita','Tequila','新时代的玛格丽特变体，去除了三倍橙酒，改用纯正的龙舌兰糖浆作为甜味剂，让基酒的植物风味更为纯粹。','shake','{"sweet": 2, "sour": 4, "bitter": 1, "strong": 4}','tommys_margarita.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-05','巴坦加','Batanga','Tequila','古巴自由的墨西哥表亲。龙舌兰与可乐的奇妙结合，粗海盐边是不可或缺的灵魂。','build','{"sweet": 3, "sour": 2, "bitter": 1, "strong": 2}','batanga.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-06','恶魔','El Diablo','Tequila','一杯隐藏着深红色诱惑的魔鬼特调。姜汁的辛辣与黑醋栗的酸甜在舌尖交锋，令人欲罢不能。','shake','{"sweet": 3, "sour": 2, "bitter": 1, "strong": 3}','el_diablo.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-07','吸血鬼','Vampiro','Tequila','墨西哥版的血腥玛丽。充满了番茄、西柚和墨西哥辣酱的狂野鲜香，是一场味蕾的刺激冒险。','shake','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 2}','vampiro.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-08','墨西哥行刑队','Mexican Firing Squad','Tequila','红石榴糖浆为龙舌兰穿上了华丽的红色外衣，而安格斯特拉苦精则在背后开出深邃的香料冷枪。','shake','{"sweet": 3, "sour": 3, "bitter": 2, "strong": 3}','mexican_firing_squad.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-09','斗牛士','Matador','Tequila','少见的龙舌兰与菠萝汁的搭配组合。菠萝的浓郁热带风情与龙舌兰的泥土气息意外地和谐。','shake','{"sweet": 3, "sour": 2, "bitter": 0, "strong": 2}','matador.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-tequila-10','小陶罐','Cantarito','Tequila','充满墨西哥街头风情的饮品。大量的新鲜柑橘果汁与龙舌兰混合，通常装在涂抹了辣盐粉的小陶罐中畅饮。','build','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 2}','cantarito.png','Traditional',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-01','莫斯科骡子','Moscow Mule','Vodka','标志性的铜马克杯中，伏特加的纯净被姜汁啤酒的辛辣和青柠的酸涩点燃，极致清凉解渴。','build','{"sweet": 2, "sour": 2, "bitter": 1, "strong": 2}','moscow_mule.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-02','大都会','Cosmopolitan','Vodka','呈诱人的粉红色，蔓越莓的微酸与柑橘伏特加的香气完美结合，是都市时尚与优雅的代名词。','shake','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 3}','cosmopolitan.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-03','血腥玛丽','Bloody Mary','Vodka','世界上最著名的解酒饮料（Hair of the Dog）。浓郁的番茄汁中加入了黑胡椒、芹菜盐、塔巴斯科辣酱等丰富的香料，像一碗冰镇的冷汤。','rolling','{"sweet": 1, "sour": 3, "bitter": 1, "strong": 2}','bloody_mary.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-04','浓缩咖啡马天尼','Espresso Martini','Vodka','完美的夜生活启动器。冷萃浓缩咖啡的苦韵与咖啡利口酒的香甜交织，摇晃后表面会形成一层细腻的咖啡油脂（Crema）。','shake','{"sweet": 3, "sour": 1, "bitter": 3, "strong": 3}','espresso_martini.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-05','白俄罗斯','White Russian','Vodka','像是一杯带酒精的冰镇拿铁。厚重的鲜奶油漂浮在伏特加与咖啡酒之上，口感丝滑，极度香甜舒适。','build','{"sweet": 4, "sour": 0, "bitter": 2, "strong": 3}','white_russian.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-06','黑俄罗斯','Black Russian','Vodka','极简主义的典范。去除了白俄罗斯的奶油，只有纯粹的伏特加冷酷与咖啡利口酒的深沉甜苦，暗黑而迷人。','build','{"sweet": 3, "sour": 0, "bitter": 2, "strong": 4}','black_russian.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-07','维斯帕','Vesper','Vodka','唯一一款同时使用金酒和伏特加作为基酒的经典马天尼变体。以开胃酒丽莱白（Lillet Blanc）代替干味美思，强劲而优雅。','shake','{"sweet": 1, "sour": 0, "bitter": 2, "strong": 5}','vesper.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-08','海风','Sea Breeze','Vodka','蔓越莓的酸甜与西柚的微苦完美中和了伏特加的酒精感，如夏日海滩上的微风般清爽宜人。','build','{"sweet": 3, "sour": 3, "bitter": 1, "strong": 1}','sea_breeze.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-09','柠檬滴','Lemon Drop','Vodka','犹如液体的酸甜柠檬糖果。杯口的糖霜中和了柠檬的酸涩，是一款极易入口的现代经典短饮。','shake','{"sweet": 4, "sour": 4, "bitter": 0, "strong": 3}','lemon_drop.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-vodka-10','咸狗','Salty Dog','Vodka','伏特加与纯西柚汁的碰撞，杯口的盐边极大程度地压制了西柚的苦味，突出了果汁的清甜。','build','{"sweet": 1, "sour": 3, "bitter": 3, "strong": 2}','salty_dog.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-01','边车','Sidecar','Brandy','最负盛名的干邑白兰地鸡尾酒。柑橘的明亮酸度完美平衡了陈年干邑的醇厚橡木香与橙味利口酒的甜美。','shake','{"sweet": 2, "sour": 3, "bitter": 1, "strong": 4}','sidecar.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-02','白兰地亚历山大','Brandy Alexander','Brandy','一杯真正的“液体甜点”。浓郁的可可香、顺滑的奶油与白兰地的醇厚融为一体，表面撒上的肉豆蔻粉是点睛之笔。','shake','{"sweet": 5, "sour": 0, "bitter": 1, "strong": 3}','brandy_alexander.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-03','皮斯科酸酒','Pisco Sour','Brandy','南美的国饮骄傲。清香扑鼻的葡萄白兰地（皮斯科）搭配青柠和糖浆，上面覆盖着厚厚的蛋白霜与几滴安格斯特拉苦精点缀。','shake','{"sweet": 3, "sour": 4, "bitter": 1, "strong": 4}','pisco_sour.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-04','老广场','Vieux Carré','Brandy','新奥尔良文化的浓缩体。黑麦威士忌的辛香、干邑的醇厚、甜味美思与廊酒（Bénédictine）的复杂草药味交织在一起。','stir','{"sweet": 3, "sour": 0, "bitter": 3, "strong": 5}','vieux_carre.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-05','法国情怀 (法国贩毒网)','French Connection','Brandy','优雅的法式双重奏。干邑白兰地的葡萄桶香与意大利苦杏仁酒的甜美无缝连接，入口温润醉人。','build','{"sweet": 4, "sour": 0, "bitter": 1, "strong": 4}','french_connection.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-06','杏仁酸酒','Amaretto Sour','Liqueur','像是液体版的杏仁蛋白软糖。柠檬的酸味完美抵消了苦杏仁酒的高甜度，加入少许波旁威士忌（现代配方）更能提升酒体结构。','shake','{"sweet": 4, "sour": 3, "bitter": 1, "strong": 2}','amaretto_sour.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-07','阿佩罗汽酒','Aperol Spritz','Liqueur','全球最受欢迎的夏日开胃酒。醒目的亮橙色，带有橘皮的微苦和普罗塞克起泡酒的清爽气泡，酒精浓度极低。','build','{"sweet": 3, "sour": 1, "bitter": 2, "strong": 1}','aperol_spritz.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-08','B52轰炸机','B-52','Liqueur','视觉效果极具冲击力的分层短饮。咖啡、百利甜与干邑形成了清晰的三色分层，最上层通常会被点燃。','build','{"sweet": 5, "sour": 0, "bitter": 1, "strong": 4}','b52.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-09','绿色蚱蜢','Grasshopper','Liqueur','像是融化的薄荷巧克力冰淇淋。呈现极其鲜艳的柔和绿色，口感顺滑浓郁，是晚宴后的完美甜点酒。','shake','{"sweet": 5, "sour": 0, "bitter": 1, "strong": 2}','grasshopper.png','IBA Official',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-brandy-10','日本拖鞋','Japanese Slipper','Liqueur','明亮的荧光绿色非常抓人眼球。蜜瓜利口酒的甜果味、三倍橙酒的柑橘味与新鲜柠檬汁的酸度完美中和，极度清新解腻。','shake','{"sweet": 4, "sour": 4, "bitter": 0, "strong": 2}','japanese_slipper.png','Classic',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-01','野格炸弹','Jägerbomb','便利店','最经典的夜店/便利店爆款组合。野格浓郁的草药味与红牛的甜腻气泡碰撞，一口闷下，瞬间提神醒脑。','build','{"sweet": 4, "sour": 1, "bitter": 2, "strong": 2}','conv_jagerbomb.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-02','微醺维C','Vodka C100','便利店','伏特加的无色无味完美隐身于水溶C100强烈的酸甜果味中。极其容易入口，小心不知不觉就喝醉了。','build','{"sweet": 3, "sour": 4, "bitter": 0, "strong": 1}','conv_vodka_c100.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-03','威士忌乌龙茶','Whiskey Oolong','便利店','成年人的深夜茶饮。三得利无糖乌龙茶醇厚的茶香与威士忌的麦芽香气相辅相成，解腻且毫无负担。','build','{"sweet": 0, "sour": 0, "bitter": 2, "strong": 2}','conv_whiskey_oolong.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-04','百利甜旺仔牛奶','Baileys Sweet Milk','便利店','加倍的奶香与甜蜜。旺仔牛奶特有的炼乳甜味与百利甜的爱尔兰威士忌奶油完美融合，仿佛在喝一杯带微醺感的奶糖。','build','{"sweet": 5, "sour": 0, "bitter": 0, "strong": 1}','conv_baileys_milk.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-05','养乐多烧酒','Soju Yakult','便利店','韩国风靡的国民喝法。烧酒的酒感被养乐多的酸甜和雪碧的气泡完全掩盖，就像在喝乳酸菌汽水。','build','{"sweet": 4, "sour": 3, "bitter": 0, "strong": 1}','conv_soju_yakult.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-06','椰林飘香 (简易版)','Easy Piña Colada','便利店','不需要繁琐地榨椰浆和打冰沙。马利宝椰子朗姆酒和便利店随手可得的椰子水或菠萝汁，10秒钟带你瞬移到夏威夷。','build','{"sweet": 3, "sour": 1, "bitter": 0, "strong": 1}','conv_malibu_coconut.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-07','甘露纯牛奶','Kahlúa Milk','便利店','比拿铁更醇厚，比咖啡多了一丝微醺。甘露咖啡利口酒与纯牛奶的结合，是晚安前最好的一杯安眠酒。','build','{"sweet": 4, "sour": 0, "bitter": 1, "strong": 1}','conv_kahlua_milk.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-08','便利店自由古巴','Cuba Libre (Conv.)','便利店','不需要专业吧台，一瓶百加得白朗姆酒版，一瓶冰可口可乐，如果能从鲜食区切一片柠檬，你就拥有一杯完美的自由古巴。','build','{"sweet": 3, "sour": 1, "bitter": 0, "strong": 2}','conv_cuba_libre.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-09','便利店金汤力','Gin Tonic (Conv.)','便利店','用最便宜的哥顿金酒加上屈臣氏汤力水，草本植物的香气和奎宁的微苦能立刻抚平一天的疲惫。','build','{"sweet": 1, "sour": 1, "bitter": 3, "strong": 2}','conv_gin_tonic.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-10','龙舌兰柚子绿茶','Tequila Grapefruit Tea','便利店','东方茶饮与墨西哥烈酒的跨界碰撞。柚子绿茶的清香甜美，竟然能完美压住银龙舌兰刺鼻的泥土味。','build','{"sweet": 3, "sour": 2, "bitter": 1, "strong": 2}','conv_tequila_tea.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-11','梅酒苏打','Umeshu Soda','便利店','俏雅梅酒加上强劲气泡的苏打水，酸甜清爽，果香四溢，是低度微醺的绝佳选择。','build','{"sweet": 4, "sour": 3, "bitter": 0, "strong": 1}','conv_umeshu_soda.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-12','伏特加燃力士','Vodka Monster','便利店','野格炸弹的伏特加变体版。Monster 魔爪能量饮料浓烈的水果味掩盖了酒精感，咖啡因+酒精的双重刺激。','build','{"sweet": 4, "sour": 2, "bitter": 1, "strong": 2}','conv_vodka_monster.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-13','三得利角瓶苏打','Kakubin Highball','便利店','日式居酒屋的灵魂饮料。只需威士忌和苏打水，配上柠檬的清香，口感极度清爽，百搭任何宵夜。','build','{"sweet": 0, "sour": 1, "bitter": 2, "strong": 2}','conv_kakubin_highball.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-14','百加得冰红茶','Bacardi Iced Tea','便利店','平民版的长岛冰茶！白朗姆的蔗糖香加上康师傅/统一冰红茶的柠檬茶香，酸甜度极高，非常好喝。','build','{"sweet": 4, "sour": 2, "bitter": 1, "strong": 2}','conv_bacardi_tea.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-15','绝对伏特加橙汁','Vodka Orange (Conv.)','便利店','其实这就是经典的螺丝起子（Screwdriver）。在便利店买一瓶汇源或味全鲜橙汁，兑上伏特加，酸甜维C满满。','build','{"sweet": 3, "sour": 2, "bitter": 0, "strong": 2}','conv_screwdriver.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-16','马利宝可乐','Malibu Cola','便利店','比起普通的自由古巴，马利宝赋予了可乐浓郁的热带椰子香草味，像是在喝一杯带有椰香风味的限量版可口可乐。','build','{"sweet": 4, "sour": 0, "bitter": 0, "strong": 1}','conv_malibu_cola.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-17','烧酒乌龙茶','Soju Oolong','便利店','韩式烧酒的草本味和乌龙茶结合，意外地刮去了烧酒的酒精感。完全无糖，热量极低。','build','{"sweet": 0, "sour": 0, "bitter": 2, "strong": 1}','conv_soju_oolong.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-18','杰克苹果打气','Jack Apple Soda','便利店','杰克丹尼苹果味威士忌加上苹果味美年达或苏打水。苹果的清香被气泡放大，酸甜爽口。','build','{"sweet": 4, "sour": 2, "bitter": 0, "strong": 2}','conv_jack_apple.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-19','桃子养乐多','Peach Yakult','便利店','绝对的“斩女”特调。桃子利口酒的甜蜜桃香与养乐多的乳酸菌酸甜完美契合，像是在吃液体的水蜜桃酸奶冰淇淋。','build','{"sweet": 5, "sour": 2, "bitter": 0, "strong": 1}','conv_peach_yakult.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780734578));
INSERT INTO recipes (id,name_zh,name_en,category,description,method,flavor_profile,image_url,source,created_at,updated_at) VALUES ('cocktail-conv-20','伏特加东方树叶','Vodka Jasmine Tea','便利店','最硬核且健康的减脂期微醺法。0糖0卡的东方树叶茉莉花茶加上同样0糖的纯粹伏特加，花香清冽，酒感纯净。','build','{"sweet": 0, "sour": 0, "bitter": 1, "strong": 2}','conv_vodka_jasmine.png','Convenience',TO_TIMESTAMP(1780734578),TO_TIMESTAMP(1780745718));
