INSERT INTO recipe_ingredients (id,recipe_id,ingredient_id,amount,unit,is_optional,display_order,created_at) VALUES ('b5df6d02-5bd9-4585-97b0-89a66b642013','cocktail-conv-17','ing-a51faa7f-1c6',120.0,'ml',false,2,TO_TIMESTAMP(1780734578));
