INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('8a1fdf13-728c-4fb5-9509-bc4057254881','cocktail-vodka-02',3,'双重过滤至冰镇的马天尼杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('d245b3a0-ddc6-4f6d-bf9e-549ba3916888','cocktail-vodka-02',4,'在杯口上方挤压点燃一片橙皮（Flared Orange Peel），然后将其投入杯中作为装饰。',TO_TIMESTAMP(1780734578));
