INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('605b3766-8ad3-4d5a-b4c3-b248d2a9e749','cocktail-vodka-03',3,'倒入高筒杯中。',TO_TIMESTAMP(1780734578));
