INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('4a1ec0da-572f-4338-bec8-7af41c0e7586','cocktail-vodka-07',3,'过滤至冰镇好的高脚马天尼杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('64237d17-4259-489a-a69d-938a7f133439','cocktail-vodka-07',4,'切一大片细长的柠檬皮，挤压出精油后投入杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('59fba5fc-dfdd-4fca-97f1-201ececfab63','cocktail-vodka-08',1,'在高筒杯中装满冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('287d1da8-cee2-4ebe-b4f3-e71e03eccdc5','cocktail-vodka-08',2,'倒入伏特加、蔓越莓汁和西柚汁。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('3b347eff-5e45-4a0b-af61-83ed106be408','cocktail-vodka-08',3,'用吧勺轻轻搅拌均匀。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('a4ee9210-cc9a-4f5f-8236-a3f03c757857','cocktail-vodka-08',4,'用一片西柚或青柠角装饰。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('29cab6c2-124b-4388-9968-1eb981a2aaf5','cocktail-vodka-09',1,'用柠檬角擦拭马天尼杯的边缘，然后蘸上一圈白砂糖（糖边）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('e5f8795f-594f-41c7-8fb4-754a08a5c8c0','cocktail-vodka-09',2,'将所有原料倒入摇酒壶。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('8f02c308-439d-41f5-988c-9825eb465ce2','cocktail-vodka-09',3,'加入冰块，剧烈摇晃以充分冷却并产生微小冰晶。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('71295bac-fb2f-4095-8a19-5ac0c7f01bcb','cocktail-vodka-09',4,'过滤至准备好糖边的杯中，用柠檬皮点缀。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('76f2a0af-6322-4af7-ac81-9fa983133ec8','cocktail-vodka-10',1,'用西柚角擦拭古典杯的边缘，蘸上一整圈粗海盐。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('3b5fdab1-b72b-486c-ad93-6082204018b6','cocktail-vodka-10',2,'在杯中轻轻放入冰块（小心不要破坏盐边）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('40135743-3870-469e-b040-bc9a7a905751','cocktail-vodka-10',3,'倒入伏特加和西柚汁。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('b15bf2d4-7e04-42db-9632-a33ef9bd0308','cocktail-vodka-10',4,'用吧勺轻轻混合即可饮用。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('dfba1269-6c35-478f-910b-69f7293053f4','cocktail-brandy-01',1,'（可选）用柠檬擦拭杯口并蘸上糖边。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('520464f9-6ded-4d31-8781-897f8cb2cba7','cocktail-brandy-01',2,'将所有原料倒入摇酒壶中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('0d143f70-341d-42fd-a8e3-aaa39457427e','cocktail-brandy-01',3,'加入冰块，剧烈摇晃。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('61eb1d13-68da-4001-99ee-de808a85d06d','cocktail-brandy-01',4,'双重过滤至冰镇的碟形杯中，用橙皮卷装饰。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('b5395624-6a73-4929-905d-b449b9c7de15','cocktail-brandy-02',1,'将所有原料倒入摇酒壶中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('6c81b0f9-4a6d-426d-b8d1-9bfdf350e9f6','cocktail-brandy-02',2,'加入大量冰块，用力摇晃直至完全乳化并冷却。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('65de7f22-2a63-44e0-a4ed-140969587de3','cocktail-brandy-02',3,'过滤至冰镇的碟形杯或马天尼杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('5e2300b0-b7b7-4ac7-a8eb-89bcb3058ab9','cocktail-brandy-02',4,'在表面现磨一些肉豆蔻粉作为装饰。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('d8d98a0e-38ad-43e3-94b2-ff3e5872ba53','cocktail-brandy-03',1,'将皮斯科、青柠汁、糖浆和蛋清倒入摇酒壶。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('780dd8bb-40be-47ca-9024-ee2c6be9eb0e','cocktail-brandy-03',2,'不加冰进行干摇（Dry Shake）约15秒，以打发蛋清。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('3623898a-f929-4c2a-bd6d-e04497f6b691','cocktail-brandy-03',3,'加入冰块，再次剧烈摇晃（Wet Shake）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('28635d7f-a8e7-401a-b75c-9ab8ac7c5430','cocktail-brandy-03',4,'双重过滤至古典杯或高脚杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('2eb9a2e9-d6ce-4216-a22c-0496bffaca7e','cocktail-brandy-03',5,'在表面的蛋白霜上滴入3滴苦精作为装饰（同时掩盖蛋腥味）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('1c640bb5-4606-45cd-ae74-b3638d364536','cocktail-brandy-04',1,'在混合杯（Mixing Glass）中加入所有原料。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('634f1b49-17e1-4e30-8466-28304eb23181','cocktail-brandy-04',2,'加入冰块，用吧勺平稳地搅拌约20-30秒至充分冷却。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('4f4460c6-4d8b-4c32-8aec-f0630c70e382','cocktail-brandy-04',3,'过滤至装有单块大冰块的古典杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('70b20fc7-1609-4049-88c4-22105e696c23','cocktail-brandy-04',4,'用柠檬皮卷或樱桃进行装饰。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('56369695-f6c8-4cb6-815b-984d93f51f7e','cocktail-brandy-05',1,'在古典杯中装满大冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('c71b189d-01bb-45d1-8949-c921f4b04100','cocktail-brandy-05',2,'倒入干邑白兰地和苦杏仁酒。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('d2ee59d3-e4f8-4462-9fac-47a5bee32fc6','cocktail-brandy-05',3,'用吧勺轻轻搅拌几下以冷却混合。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('c60153ea-f56f-4c22-9b57-eaa43f2e1c54','cocktail-brandy-05',4,'直接饮用，无需装饰（或可选橙皮卷）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('52ed4c4e-797c-4fae-8e9f-c0aff610660f','cocktail-brandy-06',1,'将所有原料倒入摇酒壶中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('0fbc964d-3ef9-4b7b-9282-ea9a5c54b2f4','cocktail-brandy-06',2,'进行干摇（Dry Shake）以打发蛋清至起泡。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('2067fa34-b7ca-4659-b6d4-e8d408fc8549','cocktail-brandy-06',3,'加入冰块，再次剧烈摇晃。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('3e0ccde0-1be5-4dfa-a18c-9cbdcc965f2d','cocktail-brandy-06',4,'过滤至装有冰块的古典杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('111df5c0-1807-4e67-a5d5-f8b4f0ece178','cocktail-brandy-06',5,'用柠檬皮卷和一颗黑樱桃装饰。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('1d5942fc-23c6-476c-9d2d-9e33d268e683','cocktail-brandy-07',1,'在大型红酒杯中装满冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('03c0d02e-b00e-4221-b11d-db56b42b787d','cocktail-brandy-07',2,'按照 3-2-1 的黄金比例：先倒入3份普罗塞克。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('3f993d9b-5f7f-4a88-ad2d-0ff749e666d5','cocktail-brandy-07',3,'接着倒入2份阿佩罗。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('d60596b6-93c1-4d30-b14b-9b477f09ac39','cocktail-brandy-07',4,'最后加入1份苏打水封顶。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('7962af7c-7e7e-4973-9e4e-e35095b59d1f','cocktail-brandy-07',5,'用吧勺轻轻从底部提拉一次，投入半片橙子装饰。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('f63c012c-1b0b-4fd4-86eb-9db46167b8e5','cocktail-brandy-08',1,'在子弹杯（Shot Glass）底层倒入咖啡利口酒。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('6163f947-389b-4a02-8601-10e97941f15f','cocktail-brandy-08',2,'将吧勺反扣抵住杯壁，顺着吧勺背面极其缓慢地倒入百利甜酒，使其漂浮在咖啡酒之上形成第二层。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('083a8e2b-8988-4924-85df-3be02e51c4a1','cocktail-brandy-08',3,'用同样的方法，将干邑或柑橘酒倒入作为最顶层。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('d26b5ada-9bd2-4319-a49f-edaf933b1c59','cocktail-brandy-08',4,'饮用前点燃最上层的烈酒（需迅速插入吸管一口吸尽）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('5eba948e-37b9-431d-bfc2-e9faa8b5d0d0','cocktail-brandy-09',1,'将所有原料倒入摇酒壶中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('753a68af-20f0-4fc6-a23f-ac65bca71f13','cocktail-brandy-09',2,'加入冰块，极其剧烈地摇晃以打发奶油产生丰富的泡沫。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('22b20563-0832-4e1f-aef6-ddfb646dfc39','cocktail-brandy-09',3,'过滤至冰镇好的马天尼杯或碟形杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('34808353-7721-428f-8421-531478013521','cocktail-brandy-09',4,'用一小枝薄荷或撒上可可粉作为点缀。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('e8589411-e760-4b74-a916-5a5a213cd60b','cocktail-brandy-10',1,'将所有三种原料等比例倒入摇酒壶中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('8d067624-5530-4180-914e-5d034aa884fd','cocktail-brandy-10',2,'加入冰块，剧烈摇晃。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('9e761b8d-abea-4bc3-9694-8b387269cfe6','cocktail-brandy-10',3,'过滤至冰镇的马天尼杯或碟形杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('7c5bc2e2-50df-400b-aa7b-635825321b51','cocktail-brandy-10',4,'在杯底沉入一颗带柄的樱桃（或用哈密瓜球点缀）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('4dd24243-d854-4c2a-a2d6-041125524da8','cocktail-conv-01',1,'在塑料杯或高筒玻璃杯中倒入大半杯红牛。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('0d03307e-139a-415d-80be-f95f6a50d1d4','cocktail-conv-01',2,'将一整小瓶野格（或将野格倒入子弹杯）直接“炸”入红牛中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('b2e93259-64f8-4051-a02c-e1746b01ab59','cocktail-conv-01',3,'趁着气泡翻腾，一口气喝完。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('c1498806-0fad-49c0-ac34-ec27a914389a','cocktail-conv-02',1,'将水溶C100喝掉或倒出四分之一的量。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('8e2def97-6e09-4abb-9ddf-bdb26dd74311','cocktail-conv-02',2,'将50ml伏特加酒版直接倒入饮料瓶中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('8126e785-07e6-4047-b388-8c65867ce3e5','cocktail-conv-02',3,'拧紧瓶盖，上下摇晃均匀即可直接对瓶吹。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('bbde7043-b2c5-447b-88ac-63191da03a06','cocktail-conv-03',1,'在便利店买一杯带冰块的塑料杯。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('cb680608-76c4-4234-86ad-aca9f61d3dcf','cocktail-conv-03',2,'倒入威士忌和乌龙茶。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('151da493-a492-429d-83cd-f100de521249','cocktail-conv-03',3,'用吸管轻轻搅拌即可享用。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('a30f5101-416f-41f8-9375-b4901eabd9a0','cocktail-conv-04',1,'将旺仔牛奶冷藏或加入少许冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('82377315-8d64-4b7c-b843-df2704bae32b','cocktail-conv-04',2,'倒入一瓶50ml的百利甜酒版。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('7a7f714b-ea77-4649-ba44-a2854ba17ef2','cocktail-conv-04',3,'摇匀或搅拌均匀即可。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('2bda7b39-4e11-4e1f-9f83-264455c934b8','cocktail-conv-05',1,'在杯中装满冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('2cb30a84-8448-4f62-9908-3e398a379aa9','cocktail-conv-05',2,'按照 1:2:2 的比例倒入烧酒、养乐多和雪碧。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('92ada886-efcc-43e4-a288-f0eb3c709448','cocktail-conv-05',3,'轻轻搅拌以防雪碧气泡跑光。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('316b797c-46d1-49ff-978c-adde81a0c792','cocktail-conv-06',1,'在杯中加入大量冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('b53b2f7f-6483-4d81-8a0d-f16ce6d26a39','cocktail-conv-06',2,'倒入马利宝和椰子水（或菠萝汁）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('2c277932-d633-42bb-af93-9af711ed73c4','cocktail-conv-06',3,'搅拌均匀即可享用。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('60b82fc2-020a-40d0-bbca-c7c92c296b5c','cocktail-conv-07',1,'在杯中放入适量冰块（也可加热牛奶热饮）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('a29d473d-7d7f-4556-bc0d-adcc80f9ed3f','cocktail-conv-07',2,'倒入纯牛奶。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('61823c1f-ac07-41bd-8369-36e8fa303850','cocktail-conv-07',3,'将甘露酒倒入其中，搅拌出好看的大理石纹理。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('a2e6f6f9-f066-488f-ac31-5c6ec347f2b6','cocktail-conv-08',1,'购买一杯便利店的冰块杯。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('fd28dfa2-0279-4195-887a-fa599ed334b3','cocktail-conv-08',2,'倒入朗姆酒版。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('d59f2301-5ef0-4b31-b387-09bc3eb3720c','cocktail-conv-08',3,'加满可乐，如果有柠檬片可以挤入少许柠檬汁并扔进杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('906096bf-f02f-4bcb-b018-c7260d616993','cocktail-conv-09',1,'在加了冰块的杯中倒入金酒。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('5ebd4e94-0f28-4132-ab4d-8abe45010194','cocktail-conv-09',2,'缓慢倒入汤力水以免气泡流失过多。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('90c6aaae-e7c1-4a2a-9114-10a48824cc14','cocktail-conv-09',3,'用吸管提拉一下即可。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('0d88335d-1245-419e-8c47-fa9308fb918b','cocktail-conv-10',1,'将柚子绿茶倒出部分。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('343cc31e-5bc4-4e21-8cbe-5a57073cd0fb','cocktail-conv-10',2,'把龙舌兰酒版倒入瓶中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('4f51f7f1-c4fd-4b6c-acf0-4414355e84ca','cocktail-conv-10',3,'摇晃均匀即可饮用。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('dce4b982-ed56-4e27-9b47-eed6a53fd665','cocktail-conv-11',1,'杯中加满冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('c605a893-484b-4d50-ae45-90c3d986863d','cocktail-conv-11',2,'倒入梅酒和苏打水（推荐比例1:2）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('1e0b7f7f-c918-4d64-8c0d-d2bf6d29e3a2','cocktail-conv-11',3,'如果有梅酒瓶里的青梅，捞出一颗放进杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('b4e10cd6-7c25-415a-9bff-27572f943cb3','cocktail-conv-12',1,'将伏特加倒入冰块杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('259720e3-7ce0-49cb-89be-b47d0c424274','cocktail-conv-12',2,'加满魔爪能量饮料。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('a7597b39-cdf9-44fd-b498-9e70726f9be4','cocktail-conv-12',3,'轻轻搅拌。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('57bd5d26-e984-4af1-a53f-4612613dfef9','cocktail-conv-13',1,'在杯中装满大量冰块（越多越好）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('8e865e98-f8b1-4798-9448-b9f4e3941fe1','cocktail-conv-13',2,'倒入威士忌，用吧勺搅拌10圈让酒体冷却。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('0acfa903-f3d3-4749-b868-0199668b9b87','cocktail-conv-13',3,'沿着杯壁缓慢倒入苏打水，放入柠檬片提香。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('8fe24153-db92-4e23-a05c-2ad1c6a900ab','cocktail-conv-14',1,'喝掉一口瓶装冰红茶。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('fd0d85b3-88b4-45b0-b9e0-b51bbb51ed86','cocktail-conv-14',2,'把朗姆酒版倒进去。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('126d8073-ce93-4d0d-95b2-58e01be2fe13','cocktail-conv-14',3,'摇晃均匀即可。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('3a8b0aec-65b0-42c6-b8c7-1d0508155211','cocktail-conv-15',1,'在杯中装满冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('fde7a51b-a975-4994-9212-52db6066cf73','cocktail-conv-15',2,'倒入伏特加和橙汁。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('6c3a5679-8e7d-436e-be10-2ace12e366b4','cocktail-conv-15',3,'搅拌均匀。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('387cf458-1b45-4c37-91ac-59f80e8aa6eb','cocktail-conv-16',1,'杯中加冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('04d5a256-a58e-44de-8926-71da9bb8b4fd','cocktail-conv-16',2,'倒入马利宝，然后加满可乐。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('ae27ee13-7ade-41ca-a08a-d1d13570ba76','cocktail-conv-16',3,'轻轻提拉搅拌以免气泡消失。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('66914d4b-17f2-417a-8ef5-940af2f859d3','cocktail-conv-17',1,'杯中加满冰块。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('4efc74df-704d-4505-8185-6132c50620a8','cocktail-conv-17',2,'以 1:2 的比例倒入烧酒和乌龙茶。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('9cb109dc-3dad-47fd-bb10-14fec21a53de','cocktail-conv-17',3,'搅拌均匀。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('3c66df42-4228-4d9f-9925-263ca36d3311','cocktail-conv-18',1,'倒入冰块杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('6210050f-4644-4a17-aa35-9f49351292e0','cocktail-conv-18',2,'按比例混合酒与气泡饮料。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('6cae0db1-687f-4256-ab94-200c9451ac4f','cocktail-conv-18',3,'轻轻搅拌出气泡即可。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('c3d4be93-9518-4346-85b4-0d5887786617','cocktail-conv-19',1,'将桃子酒倒入冰块杯中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('e4733b5f-eaf7-4fec-b182-5024f7f1f953','cocktail-conv-19',2,'倒满养乐多（通常需要1到2小瓶）。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('f10f8114-968d-426d-adfa-fbb62164c164','cocktail-conv-19',3,'搅拌均匀即可。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('39fbe6db-9cd3-4fc4-8573-528d07794db0','cocktail-conv-20',1,'喝掉一口瓶装的东方树叶。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('d4affe42-b122-48af-87dc-f5e6a99f3806','cocktail-conv-20',2,'将伏特加倒入瓶中。',TO_TIMESTAMP(1780734578));
INSERT INTO recipe_steps (id,recipe_id,step_number,instruction,created_at) VALUES ('2f4a2ef0-2f61-4683-bb9b-2fcc5ef58ebf','cocktail-conv-20',3,'摇晃均匀即可饮用。如果能加冰块风味更佳。',TO_TIMESTAMP(1780734578));
